import{_ as n,l as s,o as a,c as o,v as r,p as m,x as t,d as l,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"中介资产定价 He–Krishnamurthy","description":"","frontmatter":{"title":"中介资产定价 He–Krishnamurthy","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/intermediary-asset-pricing.md","filePath":"econ/intermediary-asset-pricing.md","lastUpdated":1789023840000}'),E={name:"econ/intermediary-asset-pricing.md"};function p(c,e,A,u,B,_){const i=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="中介资产定价-he–krishnamurthy" tabindex="-1">中介资产定价 He–Krishnamurthy <a class="header-anchor" href="#中介资产定价-he–krishnamurthy" aria-label="Permalink to &quot;中介资产定价 He–Krishnamurthy&quot;">​</a></h1><div class="epigraph"><p>家庭不能直接持有某些风险时，定价核跟着专家的净值走：专家资本一稀缺，风险价格就升。</p><footer>—— He and Krishnamurthy, Intermediary Asset Pricing, American Economic Review, 2013</footer></div><p><a href="/econ/production-based-asset-pricing">上一课</a>在完全无摩擦下让家庭与企业欧拉共用一个 \\(m\\)。本课缺口是<strong>谁能持有风险</strong>：一部分资产必须由受资本约束的中介持有，家庭只能买中介的负债。\\(m\\) 变成专家的边际价值，状态变量是中介净值。不重写投资 \\(q\\)，不把银行资本监管条文搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lucas 树假定代表性主体直接持有树。现实里许多风险（信贷、场外衍生品、部分公司债）经过经销商与银行的资产负债表。He 与 Krishnamurthy（2012, 2013）设专家有激励约束：管理的资产不能相对自己的净值无限放大。约束松时，专家接近风险中性边缘，风险价格低；约束紧时，专家的随机折现因子被净值的边际效用拉高，风险资产被甩卖、溢价升、波动升。缺口是把时变溢价的状态从总量 \\(c\\) 换成<strong>中介资本</strong>——消费可以仍平滑，风险价格照样抖。</p><p>这与信息课序的 \\(\\lambda\\) 不同：那里流动性成本来自不利选择；这里来自风险承担能力的稀缺。可以并存，本课只留资本通道。</p><p><span class="marginnote">He and Krishnamurthy, <em>AER</em> 103(2), 2013；更早的 <em>JFE</em> 2012 写危机放大。Brunnermeier–Sannikov 是连续时间宏观金融的另一条专家线，后文杠杆周期会碰到 Geanakoplos 的保证金版本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两群人：专家与家庭。家庭不能经营风险技术，只能持有无风险或中介股权/存款。专家最大化，受 skin-in-the-game 一类约束。均衡风险价格 \\(\\eta_t\\) 随专家财富份额变：份额低 → \\(\\eta\\) 高。资产价格对专家净值的敏感在约束区非线性——小损失可以大甩卖。SDF 语言：\\(m\\) 在约束区跟踪专家的 \\(u&#39;(w^e)\\)（或约束乘子），不是跟踪总量 \\(u&#39;(c)\\)。</p>',9)),(a(),m(d,null,{default:t(()=>[h(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22%E5%AE%B6%E5%BA%AD%E4%B8%8D%E8%83%BD%E7%9B%B4%E6%8E%A5%E6%8C%81%E6%9C%89%22%5D%20--%3E%20EXP%5B%22%E4%B8%93%E5%AE%B6%E6%8C%81%E6%9C%89%E9%A3%8E%E9%99%A9%22%5D%0A%20%20EXP%20--%3E%20CAP%5B%22%E5%87%80%E5%80%BC%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CAP%20--%3E%20ETA%5B%22%E9%A3%8E%E9%99%A9%E4%BB%B7%E6%A0%BC%E9%9A%8F%E5%87%80%E5%80%BC%22%5D%0A%20%20ETA%20--%3E%20PREM%5B%22%E7%BA%A6%E6%9D%9F%E7%B4%A7%3A%20%E6%BA%A2%E4%BB%B7%E4%B8%8E%E6%B3%A2%E5%8A%A8%E5%8D%87%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 <a href="/econ/capm-theory">CAPM</a>：切点加总假定人人能持有市场。中介定价说市场组合的持有人是专家，beta 应对专家的财富，而不是对家庭消费。实证用经销商杠杆、中介股票回报当代理——测量换栏；本课只陈述均衡映射。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是风险集中加杠杆约束。损失打在专家净值上，约束逼近，风险承担的影子价格升，为恢复约束他们减持风险，价格再跌，净值再损——放大。家庭想买风险也买不到（制度或激励），不能出来「抄底」把溢价立刻压回去。这与 GS 的采集不足不同：信息可以是对称的，稀缺的是资本。</p><p>生产基础的企业若自己受融资约束，企业 \\(m\\) 与专家 \\(m\\) 会连在一起：外部股权贵的时候，投资欧拉用内部影子价格。本课把专家当作加总的外部风险承担者。</p><p><span class="marginnote">约束松弛区可以接近无摩擦核，危机是状态依赖而非常态。时变溢价的 \\(D/P\\) 通道，现在多了一个可命名的 \\(z\\)：中介杠杆。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成「所以要用银行股当定价因子」的回归执照。代理是否等于专家净值，是联合假说。下一课 Brunnermeier–Pedersen 把稀缺从净值换成<strong>保证金与融资流动性</strong>，市场流动性与融资流动性互馈。本课的约束是股权式净值，下一课是抵押与 haircut。</p><p>也不要把中介写成限价簿做市商存货。存货是协议层的库存；净值是一般均衡的财富。切点仍在 <a href="/econ/to-limit-order-book">到限价簿</a>。</p><p>后课默认：部分资产必须由受约束专家持有时，\\(m\\) 跟踪专家净值；约束区风险价格非线性放大。家庭消费平滑不再是核太平的充分理由。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>专家资本约束把 \\(m\\) 从总量消费挪到中介净值。</li><li>约束紧：甩卖、溢价升、放大。</li><li>不是不利选择价差，也不是 CAPM 截面表。</li><li>出处：He and Krishnamurthy, <em>AER</em> 2013；对照 <em>JFE</em> 2012。</li></ul>',11))])}const g=n(E,[["render",p]]);export{f as __pageData,g as default};
